const GRADE_SHORT_TRAIT = {
  "초등": "초등 기초를 탄탄히 다져 중학교 과정을 자신 있게 시작합니다.",
  "중등": "내신 대비부터 고등 선행까지 체계적으로 지도합니다.",
  "고등": "수능·내신 동시 대비, 목표 대학 합격을 함께 준비합니다.",
};

// 한국어 조사 자동 처리 - 받침 유무에 따라 정확한 조사 선택
// {subject:을/를} 같은 패턴을 자연스러운 한국어로 변환
function hasJongseong(word) {
  if (!word) return false;
  const lastChar = word.charCodeAt(word.length - 1);
  // 한글 음절 영역(가-힣)인지 확인
  if (lastChar < 0xAC00 || lastChar > 0xD7A3) {
    // 한글이 아니면 영문/숫자: 보수적으로 받침 있음 처리 (대부분 자음으로 끝남)
    // 다만 모음으로 끝나는 영단어가 있으니 false가 더 안전한 편
    return false;
  }
  return (lastChar - 0xAC00) % 28 !== 0;
}

// 마지막 글자가 'ㄹ' 받침인지 (로/으로 처리용)
function endsWithRieul(word) {
  if (!word) return false;
  const lastChar = word.charCodeAt(word.length - 1);
  if (lastChar < 0xAC00 || lastChar > 0xD7A3) return false;
  return (lastChar - 0xAC00) % 28 === 8; // 'ㄹ' 받침
}

function pickJosa(word, withJong, withoutJong) {
  return hasJongseong(word) ? withJong : withoutJong;
}

function fmt(str, vars) {
  // 1. {key:josaA/josaB} 패턴 처리 - 변수 뒤에 조사 자동 선택
  // 예: {subject:을/를} → 한글 받침에 따라 "을" 또는 "를"
  // 예: {dong:로/으로} → ㄹ 받침은 "로", 다른 받침은 "으로"
  let result = str.replace(/\{(\w+):([^/}]+)\/([^}]+)\}/g, (_, k, withJong, withoutJong) => {
    const value = vars[k];
    if (value === undefined) return `{${k}:${withJong}/${withoutJong}}`;
    // 으로/로 특수 처리: 받침 없거나 ㄹ 받침이면 "로", 다른 받침은 "으로"
    if ((withJong === '으로' && withoutJong === '로') || (withJong === '로' && withoutJong === '으로')) {
      return value + (hasJongseong(value) && !endsWithRieul(value) ? '으로' : '로');
    }
    return value + pickJosa(value, withJong, withoutJong);
  });

  // 2. 일반 변수 치환
  result = result.replace(/\{(\w+)\}/g, (_, k) => vars[k] !== undefined ? vars[k] : `{${k}}`);

  // 3. 동일 지역명 중복 제거 (예: "계룡시 계룡시" → "계룡시", "계룡시 · 계룡시" → "계룡시")
  if (vars.gu && vars.dong && vars.gu === vars.dong) {
    const escGu = vars.gu.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    result = result.replace(new RegExp(escGu + '\\s*[·]?\\s*' + escGu, 'g'), vars.gu);
  }
  if (vars.city && vars.gu && vars.city === vars.gu) {
    const escCity = vars.city.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    result = result.replace(new RegExp(escCity + '\\s*[·]?\\s*' + escCity, 'g'), vars.city);
  }

  return result;
}

// 지역명 표시용 헬퍼 - 단일 지역(시·시·시) vs 다단계 지역(시·구·동) 구분
function regionVars(city, gu, dong) {
  const isSingle = (city === gu && gu === dong) || (gu === dong);
  return {
    region_full: isSingle ? gu : `${gu} ${dong}`,        // 전체 표시 (예: "계룡시" / "강남구 대치동")
    region_short: dong || gu,                             // 짧은 표시 (예: "계룡시" / "대치동")
    region_wide: gu,                                      // 넓은 표시 (예: "계룡시" / "강남구")
  };
}

function pickS(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}

function makeIntro(rng, city, gu, dong, grade, subject) {
  const reg = regionVars(city, gu, dong);
  const title = fmt(pickS(rng, INTRO_TITLES), {city,gu,dong,grade,subject,...reg});
  const body = fmt(pickS(rng, INTRO_BODIES), {
    city,gu,dong,grade,subject,...reg,
    trait_grade: pickS(rng, GRADE_TRAITS[grade]),
    trait_subject: pickS(rng, SUBJECT_TRAITS[subject] || SUBJECT_TRAITS["국어"]),
  });
  return [title, body];
}

function makeBody(rng, city, gu, dong, grade, subject) {
  const reg = regionVars(city, gu, dong);
  const title = fmt(pickS(rng, BODY_TITLES), {city,gu,dong,grade,subject,...reg});
  const body = fmt(pickS(rng, BODY_BODIES[grade]), {
    city,gu,dong,grade,subject,...reg,
    trait_subject: pickS(rng, SUBJECT_TRAITS[subject] || SUBJECT_TRAITS["국어"]),
  });
  return [title, body];
}

function makeConclusion(rng, city, gu, dong, grade, subject) {
  const reg = regionVars(city, gu, dong);
  const title = fmt(pickS(rng, CONCLUSION_TITLES), {city,gu,dong,grade,subject,...reg});
  const body = fmt(pickS(rng, CONCLUSION_BODIES), {city,gu,dong,grade,subject,...reg});
  return [title, body];
}

function makeFeatures(rng, subject, grade) {
  const pool = [...FEATURE_POOL];
  // seeded shuffle
  for (let i = pool.length-1; i>0; i--) {
    const j = Math.floor(rng() * (i+1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0,4).map(([icon,title,desc]) => [
    icon,
    fmt(title, {subject,grade}),
    fmt(desc, {subject,grade,grade_trait: GRADE_SHORT_TRAIT[grade]}),
  ]);
}
function getDisplaySubject(subj, grade) {
  if (grade === "고등") {
    if (subj === "과학") return "통합과학";
    if (subj === "사회") return "통합사회";
  }
  return subj;
}

function seededRandom(seed) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return function() {
    s = s * 16807 % 2147483647;
    return (s - 1) / 2147483646;
  };
}

function pickSeeded(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}

// ── 페이지별 의사 갱신일 생성 (SEO 최신성 시그널) ──────────────────
// 시드 기반으로 "최근 60일 이내"의 결정적 날짜를 만듦
// 같은 페이지는 항상 같은 날짜를 가지되, 60일이 지나면 자동으로 다음 사이클로 회전
const SITE_LAUNCH_DATE = new Date('2026-01-01'); // 사이트 시작 기준일

function getPageDates(slug) {
  // slug를 시드로 0~59 사이 의사 오프셋 생성 (페이지마다 다른 날짜)
  const seed = slug.split("").reduce((a,c,i) => (a + c.charCodeAt(0) * (i+1)) % 2147483647, 0);
  const offset = seed % 60; // 0~59일 분산

  const now = new Date();

  // dateModified: 오늘로부터 (offset)일 전 ~ 즉, 페이지마다 0~59일 전 사이로 분산
  const modified = new Date(now);
  modified.setDate(modified.getDate() - offset);

  // datePublished: dateModified로부터 90~180일 전 (시드로 결정)
  const pubOffset = 90 + (seed % 90); // 90~179일 추가
  const published = new Date(modified);
  published.setDate(published.getDate() - pubOffset);

  // 사이트 시작일보다 이전이면 시작일로 보정
  if (published < SITE_LAUNCH_DATE) {
    published.setTime(SITE_LAUNCH_DATE.getTime());
  }

  return {
    publishedISO: published.toISOString(),       // 2026-01-15T00:00:00.000Z (메타 태그용)
    modifiedISO: modified.toISOString(),         // 2026-04-10T00:00:00.000Z (메타 태그용)
    publishedKR: formatKoreanDate(published),    // 2026.01.15 (본문 표시용)
    modifiedKR: formatKoreanDate(modified),      // 2026.04.10 (본문 표시용)
  };
}

function formatKoreanDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}.${m}.${day}`;
}

// ── JSON-LD BreadcrumbList 생성 (SEO 구조화 데이터) ──────────────
// items: [{name: "홈", url: "https://..."}, ...]
function buildBreadcrumbJsonLd(items) {
  const itemList = items.map((item, idx) => {
    const obj = {
      "@type": "ListItem",
      "position": idx + 1,
      "name": item.name,
    };
    // 마지막 항목(현재 페이지)은 url 생략 가능 (있어도 됨, 명확성 위해 모두 포함)
    if (item.url) obj.item = item.url;
    return obj;
  });
  return `<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": ${JSON.stringify(itemList, null, 2).replace(/\n/g, '\n  ')}
}
</script>`;
}

// ── 통합 og/twitter 메타 태그 생성 (소셜 공유 최적화) ──────────────
function buildSocialMeta({ title, description, canonical, ogType = "article", imageUrl = null, imageAlt = null }) {
  const img = imageUrl || `${SITE_DOMAIN}/images/og-image.png`;
  const alt = (imageAlt || title).replace(/"/g, '&quot;');
  const safeTitle = title.replace(/"/g, '&quot;');
  const safeDesc = description.replace(/"/g, '&quot;');
  return `<meta property="og:type" content="${ogType}">
  <meta property="og:title" content="${safeTitle}">
  <meta property="og:description" content="${safeDesc}">
  <meta property="og:url" content="${canonical}">
  <meta property="og:image" content="${img}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:image:alt" content="${alt}">
  <meta property="og:site_name" content="${SITE_NAME}">
  <meta property="og:locale" content="ko_KR">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${safeTitle}">
  <meta name="twitter:description" content="${safeDesc}">
  <meta name="twitter:image" content="${img}">`;
}

// ── 공유 버튼 컴포넌트 (링크 복사 + 네이티브 공유) ─────────────────
// shareTitle: 공유 시 제목 (Web Share API용)
// shareUrl: 공유할 URL (canonical)
function buildShareButtons(shareTitle, shareUrl) {
  const safeTitle = shareTitle.replace(/'/g, "\\'").replace(/"/g, '&quot;');
  return `<div class="share-wrap" style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;padding:16px 0">
  <button onclick="(function(){const u='${shareUrl}';if(navigator.share){navigator.share({title:'${safeTitle}',url:u}).catch(()=>{});}else{navigator.clipboard.writeText(u).then(()=>{const b=event.target;const o=b.innerHTML;b.innerHTML='✅ 복사됨';setTimeout(()=>{b.innerHTML=o;},1800);});}})()" style="background:white;border:1.5px solid #510580;color:#510580;font-size:.82rem;font-weight:700;padding:8px 16px;border-radius:50px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit">📤 공유하기</button>
  <button onclick="(function(){const u='${shareUrl}';navigator.clipboard.writeText(u).then(()=>{const b=event.target;const o=b.innerHTML;b.innerHTML='✅ 복사됨';setTimeout(()=>{b.innerHTML=o;},1800);}).catch(()=>{const t=document.createElement('textarea');t.value=u;document.body.appendChild(t);t.select();document.execCommand('copy');document.body.removeChild(t);const b=event.target;const o=b.innerHTML;b.innerHTML='✅ 복사됨';setTimeout(()=>{b.innerHTML=o;},1800);});})()" style="background:white;border:1.5px solid #e8439a;color:#e8439a;font-size:.82rem;font-weight:700;padding:8px 16px;border-radius:50px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit">📋 링크 복사</button>
</div>`;
}

// ── 학년별 로드맵 카드 배너 (학교 과목 페이지 → 학년별 공부법으로 회유) ──
// level: "초등" | "중등" | "고등"
// subject: "국어" | "영어" | "수학" | "과학" | "사회" | "한국사"
const SUBJECT_KEY_MAP = {
  "국어": "korean", "영어": "english", "수학": "math",
  "과학": "science", "사회": "social", "한국사": "history",
};
const LEVEL_GRADES = {
  "초등": ["elem1", "elem2", "elem3", "elem4", "elem5", "elem6", "pre-mid1"],
  "중등": ["pre-mid1", "mid1", "mid2", "mid3", "pre-high1"],
  "고등": ["pre-high1", "high1", "high2", "high3"],
};
const GRADE_ICONS = {
  "elem1": "1️⃣", "elem2": "2️⃣", "elem3": "3️⃣", "elem4": "4️⃣", "elem5": "5️⃣", "elem6": "6️⃣",
  "pre-mid1": "⚡", "mid1": "1️⃣", "mid2": "2️⃣", "mid3": "3️⃣",
  "pre-high1": "⚡", "high1": "1️⃣", "high2": "2️⃣", "high3": "3️⃣",
};

function buildGradeRoadmapCards(level, subject) {
  const subjectKey = SUBJECT_KEY_MAP[subject];
  const grades = LEVEL_GRADES[level];
  if (!subjectKey || !grades) return "";

  const meta = GRADE_SUBJECT_META[subjectKey];
  if (!meta) return "";
  const data = meta.data();
  if (!data || Object.keys(data).length === 0) return "";

  // 예비 학년 키 정의
  const PREVIEW_GRADES = { "pre-mid1": "중학교", "pre-high1": "고등학교" };
  // 예비 학년이 현재 레벨의 마지막에 오는지 (다음 단계 미리보기)
  const isNextStep = (gradeKey) => {
    if (level === "초등" && gradeKey === "pre-mid1") return true;
    if (level === "중등" && gradeKey === "pre-high1") return true;
    return false;
  };
  // 예비 학년이 현재 레벨의 첫 번째로 오는지 (이전 단계 연계)
  const isFromPrev = (gradeKey) => {
    if (level === "중등" && gradeKey === "pre-mid1") return true;
    if (level === "고등" && gradeKey === "pre-high1") return true;
    return false;
  };

  let cards = "";
  for (const gradeKey of grades) {
    const g = data[gradeKey];
    if (!g) continue;
    const icon = GRADE_ICONS[gradeKey] || "📖";
    const href = `/study/${subjectKey}/grade/${gradeKey}/`;
    const titleParts = g.intro.title.split(",");
    const coreMessage = titleParts.length > 1 ? titleParts.slice(1).join(",").trim() : g.intro.title;

    const nextStep = isNextStep(gradeKey);
    const fromPrev = isFromPrev(gradeKey);
    const isPreview = nextStep || fromPrev;
    const previewLabel = PREVIEW_GRADES[gradeKey];

    // 예비 학년: 구분선 + 강조 스타일
    const divider = nextStep
      ? `<div style="display:flex;align-items:center;gap:8px;margin:14px 0 10px"><div style="flex:1;height:1px;background:#e8d6f5"></div><span style="font-size:.68rem;font-weight:700;color:#e8439a;white-space:nowrap">▼ ${previewLabel} 미리보기</span><div style="flex:1;height:1px;background:#e8d6f5"></div></div>`
      : fromPrev
      ? `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px"><div style="flex:1;height:1px;background:#e8d6f5"></div><span style="font-size:.68rem;font-weight:700;color:#7b2fa8;white-space:nowrap">◀ ${previewLabel} 준비 과정</span><div style="flex:1;height:1px;background:#e8d6f5"></div></div>`
      : "";

    const cardBg = isPreview ? "linear-gradient(135deg,#fef6ff,#fdf0ff)" : "white";
    const cardBorder = isPreview ? "#d4a8f5" : "#e8d6f5";
    const badgeHtml = nextStep
      ? `<span style="background:#e8439a;color:white;font-size:.6rem;font-weight:700;padding:2px 7px;border-radius:10px;white-space:nowrap">다음 단계</span>`
      : fromPrev
      ? `<span style="background:#7b2fa8;color:white;font-size:.6rem;font-weight:700;padding:2px 7px;border-radius:10px;white-space:nowrap">선행 준비</span>`
      : "";

    cards += `${divider}<a href="${href}" style="display:block;background:${cardBg};border:1px solid ${cardBorder};border-radius:12px;padding:14px 16px;margin-bottom:10px;text-decoration:none;color:inherit;transition:all .15s" onmouseover="this.style.background='#faf5ff';this.style.borderColor='#510580'" onmouseout="this.style.background='${cardBg}';this.style.borderColor='${cardBorder}'">
  <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
    <span style="font-size:1.1rem">${icon}</span>
    <span style="font-size:.92rem;font-weight:800;color:#370558">${g.tag} ${subject} 공부법</span>
    ${badgeHtml}
    <span style="margin-left:auto;color:#9b6cc0;font-size:.85rem">→</span>
  </div>
  <div style="font-size:.78rem;color:#666;line-height:1.5;padding-left:30px">${coreMessage}</div>
  <div style="font-size:.7rem;color:#9b6cc0;padding-left:30px;margin-top:4px">📚 ${g.sub}</div>
</a>`;
  }

  if (!cards) return "";

  return `<!-- 학년별 학습 로드맵 -->
<div class="sec">
  <div class="sec-label">📚 학년별 ${subject} 공부법</div>
  <div class="sec-title">${level} ${subject} 학년별 학습 로드맵</div>
  <div class="sec-body" style="margin-bottom:14px">학년별 핵심 학습 포인트와 시기별 전략을 확인해보세요. 우리 아이 학년에 맞는 가이드를 클릭하시면 자세한 공부법을 보실 수 있습니다.</div>
  <div>${cards}</div>
</div>`;
}

// ── 학교 과목 페이지의 다른 과목 카드 그리드 (CTA 위 리스트 → 카드 그리드 변환) ──
function buildOtherSubjectCards(level, currentSubject, sido, sigungu, schoolName, levelPrefix) {
  const SUBJECT_ICONS = {"국어":"📖","영어":"🌍","수학":"📐","과학":"🔬","사회":"🗺️","한국사":"📜"};
  const SUBJECT_DESC = {
    "국어": "독해·문법·서술형",
    "영어": "어법·독해·내신",
    "수학": "개념·연산·응용",
    "과학": "개념·실험·탐구",
    "사회": "지리·역사·일반사회",
    "한국사": "흐름·인물·한능검",
  };
  const subjects = ["국어","영어","수학","과학","사회","한국사"].filter(s => s !== currentSubject);

  let cards = "";
  for (const s of subjects) {
    const href = `/school/${levelPrefix}-${sido}-${sigungu}-${schoolName}-${s}-과외/`.replace(/ /g, "-").replace(/[?#&=+%]/g,"").replace(/[?#&=+%]/g,"");
    cards += `<a href="${href}" style="background:white;border:1px solid #e8d6f5;border-radius:14px;padding:16px 12px;text-decoration:none;display:flex;flex-direction:column;align-items:center;gap:6px;color:inherit;transition:all .15s" onmouseover="this.style.background='#510580';this.querySelectorAll('.osc-name,.osc-desc,.osc-cta').forEach(el=>{el.style.color='white'});this.querySelector('.osc-cta').style.background='rgba(255,255,255,0.2)'" onmouseout="this.style.background='white';this.querySelector('.osc-name').style.color='#370558';this.querySelector('.osc-desc').style.color='#9b6cc0';this.querySelector('.osc-cta').style.color='white';this.querySelector('.osc-cta').style.background='#510580'">
  <div style="font-size:1.6rem">${SUBJECT_ICONS[s]}</div>
  <div class="osc-name" style="font-size:.9rem;font-weight:800;color:#370558">${level} ${s} 과외</div>
  <div class="osc-desc" style="font-size:.7rem;color:#9b6cc0;text-align:center;line-height:1.3">${SUBJECT_DESC[s]}</div>
  <div class="osc-cta" style="margin-top:2px;background:#510580;color:white;font-size:.7rem;font-weight:700;padding:3px 10px;border-radius:20px">바로가기 →</div>
</a>`;
  }
  return cards;
}

// ── 세부 페이지 생성 ──────────────────────────────────────────
function buildDetailPage(city, gu, dong, grade, subject, slug) {
  const dispSubject = getDisplaySubject(subject, grade);
  const canonical = `${SITE_DOMAIN}/${slug}/`;
  // 단일 지역(시·시·시) 또는 시·구·구 패턴에서 중복 제거
  const reg = regionVars(city, gu, dong);
  const titleRegion = (gu === dong) ? `${city} ${gu}` : `${city} ${gu} ${dong}`;
  const titleTag = `${titleRegion} ${grade} ${subject} 과외 | ${SITE_NAME}`;
  const description = `${titleRegion} ${grade} ${dispSubject} 과외 전문 선생님을 찾고 계신가요? 제나쌤의 스터디핏 과외에서 ${reg.region_short} 인근 ${grade} ${dispSubject} 과외 선생님을 연결해 드립니다. 내신·수능 대비, 기초부터 심화까지 맞춤 수업. 무료 상담 가능.`;

  // seeded rng
  const seedVal = slug.split("").reduce((a,c,i) => (a + c.charCodeAt(0) * (i+1)) % 2147483647, 0);
  const rng = seededRandom(seedVal);

  // 페이지별 의사 갱신일 (SEO 최신성)
  const dates = getPageDates(slug);

  // JSON-LD BreadcrumbList (검색엔진용 구조화 데이터)
  const breadcrumbItems = [
    { name: "홈", url: `${SITE_DOMAIN}/` },
    { name: "지역별 과외", url: `${SITE_DOMAIN}/regions/` },
    { name: city, url: `${SITE_DOMAIN}/regions/${encodeURIComponent(city)}/` },
  ];
  if (gu !== dong) {
    breadcrumbItems.push({ name: `${gu} ${dong}`, url: canonical });
  } else {
    breadcrumbItems.push({ name: gu, url: canonical });
  }
  breadcrumbItems.push({ name: `${grade} ${dispSubject} 과외`, url: canonical });
  const breadcrumbJsonLd = buildBreadcrumbJsonLd(breadcrumbItems);

  const [introTitle, introBody] = makeIntro(rng, city, gu, dong, grade, subject);
  const [bodyTitle, bodyBody] = makeBody(rng, city, gu, dong, grade, subject);
  const [conclusionTitle, conclusionBody] = makeConclusion(rng, city, gu, dong, grade, subject);
  const features = makeFeatures(rng, subject, grade);

  const ALL_SUBJECTS = ["국어","영어","수학","과학","사회","한국사"];
  const SUBJECT_ICONS = {"국어":"📖","영어":"🌍","수학":"📐","과학":"🔬","사회":"🗺️","한국사":"📜"};
  const SUBJECT_DESC = {"국어":"독해 · 논술","영어":"문법 · 독해","수학":"개념 · 문제풀이","과학":"개념 · 원리","사회":"흐름 · 암기","한국사":"흐름 · 사건 · 암기"};
  const SUBJECT_LIST_DESC = {"국어":"독해력 · 문학 · 비문학 · 서술형 대비","영어":"문법 · 독해 · 어휘 · 내신 대비","수학":"개념 이해 · 유형 · 실전 문제풀이","과학":"개념 · 원리 이해 · 실험 정리 · 서술형","사회":"흐름 · 맥락 · 암기 전략","한국사":"시대별 흐름 · 주요 사건 · 암기 전략"};

  const relatedSubjects = ALL_SUBJECTS.filter(s => s !== subject);
  let pool = [...relatedSubjects];
  if (subject === "사회" && pool.includes("한국사")) pool = pool.filter(s => s !== "한국사");
  else if (subject === "한국사" && pool.includes("사회")) pool = pool.filter(s => s !== "사회");
  else if (pool.includes("사회") && pool.includes("한국사")) {
    pool = pool.filter(s => s !== (rng() > 0.5 ? "사회" : "한국사"));
  }
  for (let i = pool.length-1; i>0; i--) {
    const j = Math.floor(rng()*(i+1));
    [pool[i],pool[j]] = [pool[j],pool[i]];
  }


  let listHtml = "";
  for (const s of relatedSubjects) {
    const disp = getDisplaySubject(s, grade);
    const icon = SUBJECT_ICONS[s]||"📚";
    const listDesc = SUBJECT_LIST_DESC[s]||"";
    const href = `/${city}-${gu}-${dong}-${grade}-${s}-과외/`.replace(/ /g,"-");
    listHtml += `<a href="${href}" style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid #f0e6fc;text-decoration:none;background:white;transition:background .12s" onmouseover="this.style.background='#faf5ff'" onmouseout="this.style.background='white'"><div style="display:flex;align-items:center;gap:10px"><div style="width:30px;height:30px;border-radius:50%;background:#f0e6fc;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">${icon}</div><div><div style="font-size:.85rem;font-weight:700;color:#370558">${grade} ${disp} 과외</div><div style="font-size:.72rem;color:#9b6cc0;margin-top:2px">${listDesc}</div></div></div><div style="font-size:.85rem;color:#c9a3e8;flex-shrink:0">→</div></a>`;
  }
  listHtml += `<a href="/self-study/" style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid #f0e6fc;text-decoration:none;background:white;transition:background .12s" onmouseover="this.style.background='#faf5ff'" onmouseout="this.style.background='white'"><div style="display:flex;align-items:center;gap:10px"><div style="width:30px;height:30px;border-radius:50%;background:#f0e6fc;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">📋</div><div><div style="font-size:.85rem;font-weight:700;color:#370558">공부 습관 완성 과외</div><div style="font-size:.72rem;color:#9b6cc0;margin-top:2px">과목별 공부법 · 플랜 관리 · 자기주도학습</div></div></div><div style="font-size:.85rem;color:#c9a3e8;flex-shrink:0">→</div></a>`;
  listHtml += `<a href="/coding/" style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;text-decoration:none;background:white;transition:background .12s" onmouseover="this.style.background='#faf5ff'" onmouseout="this.style.background='white'"><div style="display:flex;align-items:center;gap:10px"><div style="width:30px;height:30px;border-radius:50%;background:#f0e6fc;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">💻</div><div><div style="font-size:.85rem;font-weight:700;color:#370558">AI 시대 코딩 과외</div><div style="font-size:.72rem;color:#9b6cc0;margin-top:2px">자바스크립트 · 파이썬을 통한 컴퓨팅 사고력</div></div></div><div style="font-size:.85rem;color:#c9a3e8;flex-shrink:0">→</div></a>`;

  let featuresHtml = "";
  for (const [icon, title, desc] of features) {
    featuresHtml += `<div class="feature-item"><div class="feature-icon">${icon}</div><div><div class="feature-title">${title}</div><div class="feature-desc">${desc}</div></div></div>`;
  }

  let faqHtml = "";
  for (const [q, a] of FIXED_FAQ) {
    faqHtml += `<div class="faq-item"><div class="faq-q">Q. ${q}</div><div class="faq-a">${a}</div></div>`;
  }

  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${titleTag}</title>
  <meta name="description" content="${description}">
  <link rel="canonical" href="${canonical}">
  ${buildSocialMeta({ title: titleTag, description, canonical, ogType: "article", imageAlt: `${titleRegion} ${grade} ${dispSubject} 과외` })}
  <meta property="article:published_time" content="${dates.publishedISO}">
  <meta property="article:modified_time" content="${dates.modifiedISO}">
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Article",
    "headline": "${titleTag.replace(/"/g, '\\"')}",
    "datePublished": "${dates.publishedISO}",
    "dateModified": "${dates.modifiedISO}",
    "author": {"@type": "Person", "name": "이수진"},
    "publisher": {"@type": "Organization", "name": "${SITE_NAME}", "url": "${SITE_DOMAIN}"},
    "mainEntityOfPage": {"@type": "WebPage", "@id": "${canonical}"}
  }
  </script>
  ${breadcrumbJsonLd}
  <link rel="icon" type="image/x-icon" href="/favicon.ico">
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;700;800&display=swap" rel="stylesheet">
  <style>
    ${HEADER_CSS}
    ${FLOAT_CSS}
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Noto Sans KR',sans-serif;background:#fff;color:#1a0a24;line-height:1.7}
    .wrap{max-width:680px;margin:0 auto;padding:0 16px 32px}
    .hero{background:linear-gradient(135deg,#370558,#510580,#7b2fa8);color:white;padding:36px 20px;text-align:center}
    .hero-badge{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;font-size:.72rem;font-weight:700;padding:4px 14px;margin-bottom:12px}
    .hero h1{font-size:clamp(1.4rem,4vw,2rem);font-weight:800;line-height:1.4;margin-bottom:8px;color:white}
    .hero-sub{font-size:.85rem;opacity:.85;margin-bottom:20px}
    .hero-btns{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
    .btn-white{background:white;color:#510580;padding:11px 20px;border-radius:50px;font-weight:700;font-size:.88rem;text-decoration:none}
    .btn-kakao{background:#FEE500;color:#3A1D1D;padding:11px 20px;border-radius:50px;font-weight:700;font-size:.88rem;text-decoration:none}
    .sec{background:white;border-radius:0;padding:24px 0;margin-top:0;border:none;border-bottom:1px solid #f0e6fc}
    .sec:last-of-type{border-bottom:none}
    .sec-label{font-size:.7rem;font-weight:700;color:#7b2fa8;background:#f0e6fc;display:inline-block;padding:3px 10px;border-radius:20px;margin-bottom:8px}
    .sec-title{font-size:1rem;font-weight:800;color:#370558;margin-bottom:10px;line-height:1.5}
    .sec-body{font-size:.85rem;color:#444;line-height:1.85}
    .feature-item{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-bottom:1px solid #f5eefe}
    .feature-item:last-child{border-bottom:none}
    .feature-icon{width:36px;height:36px;min-width:36px;background:#f0e6fc;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:1.1rem}
    .feature-title{font-size:.88rem;font-weight:700;color:#370558;margin-bottom:3px}
    .feature-desc{font-size:.78rem;color:#666;line-height:1.6}
    .faq-item{padding:14px 0;border-bottom:1px solid #f5eefe}
    .faq-item:last-child{border-bottom:none}
    .faq-q{font-size:.88rem;font-weight:700;color:#370558;margin-bottom:6px}
    .faq-a{font-size:.82rem;color:#555;line-height:1.75}
    .cta-sec{background:linear-gradient(135deg,#370558,#510580);border-radius:16px;padding:24px 20px;margin-top:24px;text-align:center}
    .cta-sec h2{font-size:1.1rem;font-weight:800;color:white;margin-bottom:6px}
    .cta-sec p{font-size:.82rem;color:rgba(255,255,255,.75);margin-bottom:16px}
    .cta-btns{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
    .cta-phone{background:white;color:#510580;font-size:.88rem;font-weight:700;padding:10px 18px;border-radius:50px;text-decoration:none}
    .cta-kakao{background:#FEE500;color:#3A1D1D;font-size:.88rem;font-weight:700;padding:10px 18px;border-radius:50px;text-decoration:none}
    .cta-form{background:linear-gradient(135deg,#e8439a,#ff6fc1);color:white;font-size:.88rem;font-weight:700;padding:10px 18px;border-radius:50px;text-decoration:none}
    footer{background:#370558;color:rgba(255,255,255,.45);text-align:center;padding:20px;font-size:.75rem;line-height:1.8;margin-top:0}
    footer p{color:rgba(255,255,255,.45);margin:2px 0}
    footer a{color:rgba(255,255,255,.6);text-decoration:none}
    footer a{color:rgba(255,255,255,.6);text-decoration:none}
    @media(max-width:600px){.hero-btns,.cta-btns{flex-direction:column;align-items:center}}
  </style>
</head>
<body>
${HEADER_HTML}
<div class="hero">
  <div class="hero-badge">${gu === dong ? gu : `${gu} · ${dong}`} 전문</div>
  <h1>${gu === dong ? gu : `${gu} ${dong}`}<br>${grade} ${dispSubject} 과외</h1>
  <p class="hero-sub">방문/화상 수업 · 내신/수능 맞춤 · 무료 시범수업 가능</p>
  <div class="hero-btns">
    <a href="${FORM_URL}" target="_blank" class="btn-white">📝 체험신청</a>
    <a href="${KAKAO_URL}" target="_blank" class="btn-kakao">💬 카카오톡</a>
  </div>
</div>

<div class="wrap">
  <nav style="padding:10px 0;font-size:.75rem;color:#9b6cc0">
    <a href="/" style="color:#9b6cc0;text-decoration:none">홈</a> &gt;
    <a href="/regions/" style="color:#9b6cc0;text-decoration:none">${city}</a> &gt;
    ${grade} ${dispSubject} 과외
  </nav>

  <div style="display:flex;align-items:center;gap:8px;padding:6px 0;font-size:.7rem;color:#999;border-bottom:1px solid #f5eefe">
    <span>📅 최종 업데이트: ${dates.modifiedKR}</span>
    <span style="color:#ddd">|</span>
    <span>최초 게시: ${dates.publishedKR}</span>
  </div>

  <!-- 서론 -->
  <div class="sec">
    <div class="sec-label">과외 소개</div>
    <div class="sec-title">${introTitle}</div>
    <div class="sec-body">${introBody}</div>
  </div>

  <!-- 수업 특징 -->
  <div class="sec">
    <div class="sec-label">수업 특징</div>
    <div class="sec-title">제나쌤스터디핏 과외가 다른 이유</div>
    ${featuresHtml}
  </div>

  <!-- 본론 -->
  <div class="sec">
    <div class="sec-label">수업 안내</div>
    <div class="sec-title">${bodyTitle}</div>
    <div class="sec-body">${bodyBody}</div>
  </div>

  ${buildGradeRoadmapCards(grade, subject)}

  <!-- 이미지 그리드 -->
  <div style="margin-top:24px;display:flex;flex-direction:column;gap:12px">
    <img src="/images/study-01-desk.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-02-book.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-03-writing.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-04-tutoring.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-05-whiteboard.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-06-math.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-07-english.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-08-korean.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-09-science.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-10-social.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-11-result.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-12-feedback.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
    <img src="/images/study-13-smile.jpg" alt="${dong} ${grade} ${subject} 과외 수업 사진" loading="lazy" style="width:100%;height:auto;border-radius:10px;border:1px solid #e8d6f5;display:block">
  </div>

  <!-- 결론 -->
  <div class="sec">
    <div class="sec-label">마무리</div>
    <div class="sec-title">${conclusionTitle}</div>
    <div class="sec-body">${conclusionBody}</div>
  </div>

  <!-- FAQ -->
  <div style="background:#faf5ff;border-radius:14px;padding:20px;margin-top:24px;border:1px solid #e8d6f5">
    <div class="sec-label">자주 묻는 질문</div>
    <div class="sec-title">과외 신청 전 궁금한 점</div>
    ${faqHtml}
  </div>

  <!-- CTA -->
  <div class="cta-sec">
    <h2>지금 바로 무료 상담받으세요</h2>
    <p>${gu === dong ? gu : `${gu} ${dong}`} ${grade} ${dispSubject} 과외 — 빠른 상담, 맞춤 배정</p>
    <div class="cta-btns">
      <a href="tel:${PHONE}" class="cta-phone">📞 전화</a>
      <a href="${KAKAO_URL}" target="_blank" class="cta-kakao">💬 카카오톡</a>
      <a href="${FORM_URL}" target="_blank" class="cta-form">📝 체험신청</a>
    </div>
  </div>

  ${buildShareButtons(titleTag, canonical)}

  <!-- 리스트형 관련 과목 -->
  <div style="background:white;border:1px solid #e8d6f5;border-radius:14px;overflow:hidden;margin-top:10px;margin-bottom:48px">
    <div style="padding:13px 16px;border-bottom:1px solid #f0e6fc;background:#faf5ff;display:flex;align-items:center;justify-content:space-between">
      <span style="font-size:.88rem;font-weight:700;color:#370558">${dong} ${grade} 다른 과목 과외</span>
      <span style="font-size:.72rem;color:#9b6cc0">클릭해서 바로 확인 →</span>
    </div>
    ${listHtml}
  </div>
</div>

${FOOTER_HTML}
${FLOAT_HTML}
</body>
</html>`;
}

// ── 메인 페이지 ───────────────────────────────────────────────
function buildMainPage() {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>전국 방문·화상 과외 전문 | ${SITE_NAME}</title>
  <meta name="description" content="베테랑 선생님의 1:1 맞춤 과외. 초·중·고 전과목 내신 전문. 무료 시범수업 신청 가능.">
  <link rel="canonical" href="${SITE_DOMAIN}/">
  <meta property="og:type" content="website">
  <meta property="og:title" content="전국 방문·화상 과외 전문 | ${SITE_NAME}">
  <meta property="og:image" content="${SITE_DOMAIN}/images/og-image.png">
  <link rel="icon" type="image/x-icon" href="/favicon.ico">
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;700;800&display=swap" rel="stylesheet">
  <style>
    ${HEADER_CSS}
    ${FLOAT_CSS}
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Noto Sans KR',sans-serif;background:#fff;color:#1a0a24;line-height:1.7}
    .hero{background:linear-gradient(140deg,#370558,#510580,#7b2fa8);color:white;padding:60px 24px;text-align:center}
    .hero-badge{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;font-size:.78rem;font-weight:700;padding:5px 16px;margin-bottom:16px}
    .hero h1{font-size:clamp(1.8rem,4vw,2.8rem);font-weight:800;line-height:1.4;margin-bottom:10px;color:white}
    .hero p{font-size:.95rem;opacity:.85;margin-bottom:28px}
    .hero-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
    .btn-pink{background:linear-gradient(135deg,#e8439a,#ff6fc1);color:white;padding:13px 28px;border-radius:50px;font-weight:700;font-size:.95rem;text-decoration:none;box-shadow:0 4px 14px rgba(232,67,154,.4)}
    .btn-outline-w{background:transparent;color:white;padding:13px 28px;border-radius:50px;font-weight:700;font-size:.95rem;border:1.5px solid rgba(255,255,255,.5);text-decoration:none}
    .stats{background:#370558;padding:24px}
    .stats-inner{max-width:900px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;text-align:center}
    .stat-num{font-size:1.6rem;font-weight:800;color:white}
    .stat-label{font-size:.75rem;color:rgba(255,255,255,.6);margin-top:4px}
    .sec{max-width:900px;margin:0 auto;padding:52px 24px}
    .sec-label{display:inline-block;font-size:.72rem;font-weight:700;color:#7b2fa8;background:#f0e6fc;padding:4px 12px;border-radius:20px;margin-bottom:10px}
    .sec-title{font-size:clamp(1.4rem,3vw,2rem);font-weight:800;color:#1a0a24;line-height:1.4;margin-bottom:8px}
    .sec-sub{font-size:.9rem;color:#666;line-height:1.8;margin-bottom:32px}
    .sec-divider{border:none;border-top:1px solid #f0e6fc;margin:0}
    .diag-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px}
    .diag-card{background:#faf5ff;border:1px solid #e8d6f5;border-radius:14px;padding:20px}
    .diag-num{font-size:.75rem;font-weight:800;color:#7b2fa8;margin-bottom:8px}
    .diag-title{font-size:.95rem;font-weight:800;color:#370558;margin-bottom:6px}
    .diag-desc{font-size:.82rem;color:#666;line-height:1.6}
    .sys-step{display:flex;gap:16px;align-items:flex-start;padding:16px 0;border-bottom:1px solid #f0e6fc}
    .sys-step:last-child{border-bottom:none}
    .step-num{width:36px;height:36px;border-radius:50%;background:#510580;color:white;font-size:.88rem;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px}
    .step-title{font-size:.95rem;font-weight:800;color:#370558;margin-bottom:4px}
    .step-desc{font-size:.82rem;color:#666;line-height:1.6}
    .teacher-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px}
    .teacher-card{background:#faf5ff;border:1px solid #e8d6f5;border-radius:14px;padding:20px}
    .teacher-icon{font-size:1.8rem;margin-bottom:10px}
    .teacher-title{font-size:.95rem;font-weight:800;color:#370558;margin-bottom:6px}
    .teacher-desc{font-size:.82rem;color:#666;line-height:1.6}
    /* 수업 찾기 */
    .find-tabs{display:flex;justify-content:center;gap:8px;margin:20px 0 24px;flex-wrap:wrap}
    .find-tab{background:white;color:#370558;border:1.5px solid #e8d6f5;border-radius:50px;padding:10px 22px;font-size:.88rem;font-weight:700;cursor:pointer;font-family:inherit;transition:all .15s}
    .find-tab:hover{border-color:#510580;background:#faf5ff}
    .find-tab-active{background:#510580;color:white;border-color:#510580}
    .find-tab-active:hover{background:#370558;border-color:#370558}
    .find-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;max-width:900px;margin:0 auto}
    .find-grid-subject{grid-template-columns:repeat(2,1fr)}
    .find-card{display:flex;align-items:center;gap:10px;padding:14px 18px;background:white;border:1px solid #e8d6f5;border-radius:10px;text-decoration:none;color:#370558;font-weight:700;transition:all .15s}
    .find-card:hover{border-color:#510580;background:#faf5ff;transform:translateY(-1px)}
    .find-icon{font-size:1.1rem;flex-shrink:0}
    .find-name{font-size:.92rem}
    .img-banner{position:relative;height:280px;overflow:hidden}
    .img-banner img{width:100%;height:100%;object-fit:cover;filter:brightness(.5)}
    .img-overlay{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);text-align:center;color:white}
    .img-overlay-title{font-size:clamp(1.4rem,3vw,2rem);font-weight:800;line-height:1.4;margin-bottom:10px}
    .img-overlay-sub{font-size:.9rem;opacity:.85}
    .review-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}
    .review-card{background:white;border:1px solid #e8d6f5;border-radius:14px;padding:20px}
    .review-badge{display:inline-block;font-size:.72rem;font-weight:700;color:#510580;background:#f0e6fc;padding:3px 10px;border-radius:20px;margin-bottom:10px}
    .review-text{font-size:.85rem;color:#370558;line-height:1.7;margin-bottom:12px;font-style:italic}
    .review-author{font-size:.75rem;color:#9b6cc0;font-weight:700}
    .cta-sec{background:linear-gradient(140deg,#370558,#510580);padding:60px 24px;text-align:center}
    .cta-sec h2{font-size:clamp(1.4rem,3vw,2rem);font-weight:800;color:white;margin-bottom:10px}
    .cta-sec p{font-size:.9rem;color:rgba(255,255,255,.75);margin-bottom:28px}
    .cta-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
    .cta-phone{background:white;color:#510580;font-size:.95rem;font-weight:800;padding:13px 22px;border-radius:50px;text-decoration:none}
    .cta-kakao{background:#FEE500;color:#3A1D1D;font-size:.95rem;font-weight:800;padding:13px 22px;border-radius:50px;text-decoration:none;display:inline-flex;align-items:center;gap:6px}
    .cta-form{background:linear-gradient(135deg,#e8439a,#ff6fc1);color:white;font-size:.95rem;font-weight:800;padding:13px 22px;border-radius:50px;text-decoration:none}
    footer{background:#370558;color:rgba(255,255,255,.45);text-align:center;padding:24px;font-size:.78rem;line-height:1.8}
    footer p{color:rgba(255,255,255,.45);margin:2px 0}
    footer a{color:rgba(255,255,255,.6);text-decoration:none}
    @media(max-width:600px){.stats-inner{grid-template-columns:repeat(2,1fr)}.hero-btns,.cta-btns{flex-direction:column;align-items:center}}
    @media(min-width:768px){
      .find-grid{grid-template-columns:repeat(6,1fr);gap:10px}
      .find-grid-subject{grid-template-columns:repeat(4,1fr);max-width:960px}
      .find-card{padding:16px 20px}
      .find-icon{font-size:1.2rem}
      .find-name{font-size:1rem}
    }
  </style>
</head>
<body>
${HEADER_HTML}
<div class="hero">
  <div class="hero-badge">전국 방문 · 화상 과외 전문</div>
  <h1>우리 아이 성적 향상,<br>베테랑 선생님과 함께</h1>
  <p>전문 선생님의 1:1 맞춤 수업 · 초·중·고 전과목 내신 전문</p>
  <div class="hero-btns">
    <a href="${FORM_URL}" class="btn-pink" target="_blank">📝 체험신청</a>
    <a href="/regions/" class="btn-outline-w">지역별 과외 찾기 →</a>
  </div>
</div>
<div class="stats">
  <div class="stats-inner">
    <div><div class="stat-num">1:1</div><div class="stat-label">완전 맞춤 수업</div></div>
    <div><div class="stat-num">전과목</div><div class="stat-label">초·중·고 전과목</div></div>
    <div><div class="stat-num">방문·화상</div><div class="stat-label">수업 방식 선택</div></div>
    <div><div class="stat-num">무료</div><div class="stat-label">시범수업 제공</div></div>
  </div>
</div>

<!-- 진단 검사 -->
<div style="background:#fff">
<div class="sec">
  <div class="sec-label">진단 검사</div>
  <div class="sec-title">우리 아이의 학습 상태,<br>정확하게 파악하고 있나요?</div>
  <div class="sec-sub">표면적인 성적만으로는 진짜 문제를 알 수 없습니다.<br>상담 전 학습 진단으로 맞춤 학습 방향을 설계해 드립니다.</div>
  <div class="diag-grid">
    <div class="diag-card"><div class="diag-num">01</div><div class="diag-title">학습 수준 진단</div><div class="diag-desc">현재 학습 수준과 취약 단원을 정확히 파악합니다</div></div>
    <div class="diag-card"><div class="diag-num">02</div><div class="diag-title">학습 성향 분석</div><div class="diag-desc">아이에 맞는 최적의 학습 방법을 찾습니다</div></div>
    <div class="diag-card"><div class="diag-num">03</div><div class="diag-title">목표 설정 상담</div><div class="diag-desc">내신·수능 목표에 맞는 단기·장기 플랜을 수립합니다</div></div>
    <div class="diag-card"><div class="diag-num">04</div><div class="diag-title">선생님 매칭</div><div class="diag-desc">진단 결과를 바탕으로 최적의 선생님을 배정합니다</div></div>
  </div>
</div>
</div>

<hr class="sec-divider">

<!-- 학습 시스템 -->
<div style="background:#faf5ff">
<div class="sec">
  <div class="sec-label">학습 시스템</div>
  <div class="sec-title">수업 시작부터 성적 향상까지<br>체계적인 5단계 관리</div>
  <div class="sec-sub">단순한 과외가 아닙니다. 처음부터 끝까지 책임지는 시스템입니다.</div>
  <div class="sys-step"><div class="step-num">1</div><div><div class="step-title">무료 상담 · 진단</div><div class="step-desc">학생의 현재 수준, 목표 성적, 학습 성향을 파악합니다</div></div></div>
  <div class="sys-step"><div class="step-num">2</div><div><div class="step-title">선생님 매칭</div><div class="step-desc">진단 결과에 맞는 검증된 전담 선생님을 배정합니다</div></div></div>
  <div class="sys-step"><div class="step-num">3</div><div><div class="step-title">무료 시범수업</div><div class="step-desc">첫 수업은 무료로 진행, 수업 방향을 확인하고 결정합니다</div></div></div>
  <div class="sys-step"><div class="step-num">4</div><div><div class="step-title">맞춤 커리큘럼 수업</div><div class="step-desc">학생 목표에 맞는 커리큘럼으로 매주 체계적으로 수업합니다</div></div></div>
  <div class="sys-step"><div class="step-num">5</div><div><div class="step-title">정기 피드백 · 성적 관리</div><div class="step-desc">수업 후 학부모님께 학습 현황을 피드백, 성적 향상을 함께 관리합니다</div></div></div>
</div>
</div>

<hr class="sec-divider">

<!-- 선생님 자질 -->
<div style="background:#fff">
<div class="sec">
  <div class="sec-label">선생님 자질 · 역량</div>
  <div class="sec-title">아무 선생님이 아닙니다<br>검증된 베테랑 선생님입니다</div>
  <div class="sec-sub">제나쌤 스터디핏의 선생님은 까다로운 검증 과정을 통과한 분들입니다.</div>
  <div class="teacher-grid">
    <div class="teacher-card"><div class="teacher-icon">🎓</div><div class="teacher-title">학력 · 경력 검증</div><div class="teacher-desc">출신 대학, 전공, 과외 경력을 꼼꼼히 확인합니다</div></div>
    <div class="teacher-card"><div class="teacher-icon">📋</div><div class="teacher-title">수업 역량 평가</div><div class="teacher-desc">실제 수업 방식과 설명력을 직접 평가합니다</div></div>
    <div class="teacher-card"><div class="teacher-icon">💬</div><div class="teacher-title">소통 능력</div><div class="teacher-desc">학생·학부모와의 원활한 소통 능력을 중요시합니다</div></div>
    <div class="teacher-card"><div class="teacher-icon">🔄</div><div class="teacher-title">선생님 교체 보장</div><div class="teacher-desc">수업이 맞지 않으면 언제든 선생님을 교체해 드립니다</div></div>
  </div>
</div>
</div>

<!-- 수업 찾기 -->
<div style="background:#faf5ff">
<div class="sec">
  <div class="sec-label">FIND YOUR CLASS</div>
  <div class="sec-title">수업 찾기</div>
  <div class="sec-sub">원하는 카테고리를 선택하세요</div>
  <div class="find-tabs">
    <button class="find-tab find-tab-active" data-tab="region">📍 지역별 과외</button>
    <button class="find-tab" data-tab="subject">📚 과목별 과외</button>
  </div>
  <div class="find-grid find-grid-region" id="find-region">
    <a href="/regions/#city-서울특별시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">서울</span></a>
    <a href="/regions/#city-경기도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">경기</span></a>
    <a href="/regions/#city-인천광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">인천</span></a>
    <a href="/regions/#city-부산광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">부산</span></a>
    <a href="/regions/#city-대구광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">대구</span></a>
    <a href="/regions/#city-대전광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">대전</span></a>
    <a href="/regions/#city-광주광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">광주</span></a>
    <a href="/regions/#city-울산광역시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">울산</span></a>
    <a href="/regions/#city-세종시" class="find-card"><span class="find-icon">🔸</span><span class="find-name">세종</span></a>
    <a href="/regions/#city-강원도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">강원</span></a>
    <a href="/regions/#city-충청북도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">충북</span></a>
    <a href="/regions/#city-충청남도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">충남</span></a>
    <a href="/regions/#city-전라북도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">전북</span></a>
    <a href="/regions/#city-전라남도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">전남</span></a>
    <a href="/regions/#city-경상북도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">경북</span></a>
    <a href="/regions/#city-경상남도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">경남</span></a>
    <a href="/regions/#city-제주도" class="find-card"><span class="find-icon">🔸</span><span class="find-name">제주</span></a>
  </div>
  <div class="find-grid find-grid-subject" id="find-subject" style="display:none">
    <a href="/study/korean/" class="find-card"><span class="find-icon">📖</span><span class="find-name">국어</span></a>
    <a href="/study/english/" class="find-card"><span class="find-icon">🌍</span><span class="find-name">영어</span></a>
    <a href="/study/math/" class="find-card"><span class="find-icon">📐</span><span class="find-name">수학</span></a>
    <a href="/study/science/" class="find-card"><span class="find-icon">🔬</span><span class="find-name">과학</span></a>
    <a href="/study/social/" class="find-card"><span class="find-icon">🗺️</span><span class="find-name">사회</span></a>
    <a href="/study/history/" class="find-card"><span class="find-icon">📜</span><span class="find-name">한국사</span></a>
    <a href="/coding/" class="find-card"><span class="find-icon">💻</span><span class="find-name">코딩</span></a>
    <a href="/self-study/" class="find-card"><span class="find-icon">📋</span><span class="find-name">자기주도학습</span></a>
  </div>
</div>
</div>
<script>
(function(){
  var tabs = document.querySelectorAll('.find-tab');
  tabs.forEach(function(tab){
    tab.addEventListener('click', function(){
      tabs.forEach(function(t){ t.classList.remove('find-tab-active'); });
      tab.classList.add('find-tab-active');
      var target = tab.getAttribute('data-tab');
      document.getElementById('find-region').style.display = (target === 'region') ? '' : 'none';
      document.getElementById('find-subject').style.display = (target === 'subject') ? '' : 'none';
    });
  });
})();
</script>

<!-- 이미지 배너 -->
<div class="img-banner">
  <img src="/images/main-banner.jpg" alt="공부하는 학생">
  <div class="img-overlay">
    <div class="img-overlay-title">우리 아이의 성적,<br>지금 바로 바꿀 수 있습니다</div>
    <div class="img-overlay-sub">베테랑 선생님과 1:1 맞춤 수업으로 시작하세요</div>
  </div>
</div>

<!-- 수업 후기 -->
<div style="background:#faf5ff">
<div class="sec">
  <div class="sec-label">수업 후기</div>
  <div class="sec-title">실제 수강생 후기로<br>직접 확인하세요</div>
  <div class="sec-sub">수강생 가족분들의 솔직한 후기입니다.</div>
  <div class="review-grid">
    <div class="review-card"><div class="review-badge">중3 · 수학</div><div class="review-text">"수학을 포기했던 아이가 선생님 만나고 3개월 만에 60점대에서 90점대로 올랐어요."</div><div class="review-author">남양주시 학부모</div></div>
    <div class="review-card"><div class="review-badge">고1 · 영어</div><div class="review-text">"내신 준비를 체계적으로 도와주셔서 처음으로 영어 1등급 받았습니다."</div><div class="review-author">구리시 학부모</div></div>
    <div class="review-card"><div class="review-badge">초5 · 국어</div><div class="review-text">"선생님이 흥미롭게 수업해 주셔서 책 읽는 걸 좋아하게 됐어요!"</div><div class="review-author">서울 강동구 학부모</div></div>
  </div>
</div>
</div>

<div class="cta-sec">
  <h2>지금 바로 무료 상담 받으세요</h2>
  <p>상담 후 무료 시범수업까지 — 부담 없이 시작하세요</p>
  <div class="cta-btns">
    <a href="tel:${PHONE}" class="cta-phone">📞 전화</a>
    <a href="${KAKAO_URL}" target="_blank" class="cta-kakao">
      <svg width="16" height="16" viewBox="0 0 24 24"><path d="M12 3C6.477 3 2 6.477 2 10.8c0 2.7 1.644 5.08 4.148 6.538L5.2 20.4a.3.3 0 0 0 .438.328l4.07-2.7A11.4 11.4 0 0 0 12 18.6c5.523 0 10-3.477 10-7.8S17.523 3 12 3z" fill="#3A1D1D"/></svg>
      카카오톡
    </a>
    <a href="${FORM_URL}" target="_blank" class="cta-form">📝 체험신청</a>
  </div>
</div>
${FOOTER_HTML}
${FLOAT_HTML}
</body>
</html>`;
}

// ── 지역 페이지 ───────────────────────────────────────────────
function buildRegionsPage() {
  // 시도 → 시(구 포함) → 구 → 동 3단계 구조로 그룹화
  // gu가 "고양시 덕양구" 형태면 → si="고양시", gu="덕양구"
  // gu가 "강남구" 형태면 → si=null, gu="강남구"

  const cityMap = {}; // city → siMap
  // siMap: si → guMap (si가 없으면 "__direct__" 키 사용)
  // guMap: gu → Set(dongs)

  for (const [city, gu, dong] of AREAS) {
    if (!cityMap[city]) cityMap[city] = {};
    let si, realGu;
    if (gu.includes(' ')) {
      const parts = gu.split(' ');
      si = parts[0];
      realGu = parts[1];
    } else {
      si = '__direct__';
      realGu = gu;
    }
    if (!cityMap[city][si]) cityMap[city][si] = {};
    if (!cityMap[city][si][realGu]) cityMap[city][si][realGu] = new Set();
    cityMap[city][si][realGu].add(dong);
  }

  const sortedCities = [...Object.keys(cityMap)].sort((a, b) => {
    const ai = CITY_ORDER.indexOf(a);
    const bi = CITY_ORDER.indexOf(b);
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
  });

  let cityBlocksHtml = "";

  for (const city of sortedCities) {
    const siMap = cityMap[city];
    const cityKey = city.replace(/ /g, "_");

    // 전체 ㄱㄴㄷ 정렬 — __direct__ 안의 gu와 si 합쳐서 정렬
    const allItems = []; // {label, type: 'direct'|'si', si, guMap}
    for (const [gu, dongs] of Object.entries(siMap.__direct__ || {})) {
      allItems.push({ label: gu, type: 'direct', gu, dongs });
    }
    for (const si of Object.keys(siMap).filter(s => s !== '__direct__')) {
      allItems.push({ label: si, type: 'si', si, guMap: siMap[si] });
    }
    allItems.sort((a, b) => a.label.localeCompare(b.label));

    let siPillsHtml = "";
    let siAreasHtml = "";
    let totalCount = 0;

    for (const item of allItems) {
      totalCount++;
      if (item.type === 'direct') {
        const { gu, dongs } = item;
        const guKey = `${cityKey}_${gu.replace(/ /g, "_")}`;
        const dongArr = Array.from(dongs).sort();
        // 동이 1개이고 gu와 이름이 같으면 (거창군→거창군 등) 바로 페이지 링크
        if (dongArr.length === 1 && dongArr[0] === gu) {
          const href = `/${city}-${gu}-${gu}-중등-수학-과외/`.replace(/ /g, "-");
          siPillsHtml += `<a href="${href}" class="gu-pill" data-city="${city}" data-gu="${gu}" data-dong="${gu}" style="text-decoration:none;display:inline-block">${gu}</a>`;
        } else {
          siPillsHtml += `<button class="gu-pill" onclick="toggleDong('${cityKey}','${guKey}')" id="pill_${guKey}">${gu}</button>`;
          let dongChips = "";
          for (const dong of dongArr) {
            const href = `/${city}-${gu}-${dong}-중등-수학-과외/`.replace(/ /g, "-");
            dongChips += `<a href="${href}" class="dong-chip" data-city="${city}" data-gu="${gu}" data-dong="${dong}">${dong}</a>`;
          }
          siAreasHtml += `<div class="dong-area" id="dong_${guKey}" style="display:none">
  <div class="dong-area-header">
    <span class="dong-area-title">${gu} · 동/읍/면 선택</span>
    <span class="dong-area-close" onclick="closeDong('${cityKey}','${guKey}')">닫기 ✕</span>
  </div>
  <div class="dong-chips">${dongChips}</div>
</div>`;
        }
      } else {
        const { si, guMap } = item;
        const siKey = `${cityKey}_${si.replace(/ /g, "_")}`;
        siPillsHtml += `<button class="si-pill" onclick="toggleSi('${cityKey}','${siKey}')" id="sipill_${siKey}">${si}</button>`;
        let guPillsHtml2 = "";
        let dongAreasHtml2 = "";
        for (const [gu, dongs] of Object.entries(guMap).sort((a,b) => a[0].localeCompare(b[0]))) {
          const guKey = `${siKey}_${gu.replace(/ /g, "_")}`;
          guPillsHtml2 += `<button class="gu-pill2" onclick="toggleDong2('${siKey}','${guKey}')" id="pill2_${guKey}">${gu}</button>`;
          let dongChips = "";
          for (const dong of Array.from(dongs).sort()) {
            const fullGu = si + ' ' + gu;
            const href = `/${city}-${fullGu}-${dong}-중등-수학-과외/`.replace(/ /g, "-");
            dongChips += `<a href="${href}" class="dong-chip" data-city="${city}" data-gu="${fullGu}" data-dong="${dong}">${dong}</a>`;
          }
          dongAreasHtml2 += `<div class="dong-area2" id="dong2_${guKey}" style="display:none">
  <div class="dong-area-header">
    <span class="dong-area-title">${si} ${gu} · 동/읍/면 선택</span>
    <span class="dong-area-close" onclick="closeDong2('${siKey}','${guKey}')">닫기 ✕</span>
  </div>
  <div class="dong-chips">${dongChips}</div>
</div>`;
        }
        siAreasHtml += `<div class="si-area" id="siarea_${siKey}" style="display:none">
  <div class="gu-pills2">${guPillsHtml2}</div>
  ${dongAreasHtml2}
</div>`;
      }
    }

    cityBlocksHtml += `<div class="city-block" id="city-${city}" data-city="${city}">
  <div class="city-header">
    <span class="city-name">${city}</span>
    <span class="city-count">${totalCount}개 구/시</span>
  </div>
  <div class="city-body">
    <div class="gu-pills">${siPillsHtml}</div>
    ${siAreasHtml}
  </div>
</div>`;
  }

  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>지역별 과외 찾기 | ${SITE_NAME}</title>
  <meta name="description" content="전국 방문·화상 과외 전문. 베테랑 선생님의 초·중·고 전과목 내신 맞춤 수업.">
  <link rel="canonical" href="${SITE_DOMAIN}/regions/">
  <meta property="og:image" content="${SITE_DOMAIN}/images/og-image.png">
  <link rel="icon" type="image/x-icon" href="/favicon.ico">
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;700;800&display=swap" rel="stylesheet">
  <style>
    ${HEADER_CSS}
    ${FLOAT_CSS}
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Noto Sans KR',sans-serif;background:#fff;color:#1a0a24}
    .hero{background:linear-gradient(140deg,#370558,#510580);color:white;padding:40px 24px;text-align:center}
    .hero h1{font-size:clamp(1.4rem,3vw,2rem);font-weight:800;color:white;margin-bottom:8px}
    .hero p{font-size:.88rem;opacity:.85}
    .filter-bar{background:white;padding:12px 20px;border-bottom:1px solid #e8d6f5;display:flex;gap:10px;align-items:center;flex-wrap:wrap;position:sticky;top:57px;z-index:100}
    .filter-label{font-size:.78rem;font-weight:700;color:#7b2fa8}
    .filter-select{border:1px solid #e8d6f5;border-radius:8px;padding:6px 10px;font-size:.82rem;color:#370558;background:white;cursor:pointer}
    .filter-search{border:1px solid #e8d6f5;border-radius:8px;padding:6px 12px;font-size:.82rem;color:#370558;flex:1;min-width:120px}
    .main-wrap{max-width:960px;margin:0 auto;padding:20px 16px}
    .city-block{background:white;border-radius:14px;border:1px solid #e8d6f5;margin-bottom:12px;overflow:hidden}
    .city-header{display:flex;justify-content:space-between;align-items:center;padding:13px 18px;background:#faf5ff;border-bottom:1px solid #f0e6fc}
    .city-name{font-size:.95rem;font-weight:800;color:#370558}
    .city-count{font-size:.72rem;color:#9b6cc0}
    .city-body{padding:14px 18px}
    .gu-pills{display:flex;flex-wrap:wrap;gap:8px}
    .si-pill,.gu-pill{background:#f0e6fc;border:1px solid #d4b8f5;border-radius:10px;padding:8px 18px;font-size:.88rem;font-weight:700;color:#510580;cursor:pointer;transition:all .15s}
    .si-pill:hover,.si-pill.active,.gu-pill:hover,.gu-pill.active{background:#510580;color:white;border-color:#510580}
    .si-area{margin-top:10px;padding:12px 14px;background:#f7f3fb;border-radius:10px;border:1px solid #e8d6f5;display:none}
    .gu-pills2{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:4px}
    .gu-pill2{background:#f0e6fc;border:1px solid #d4b8f5;border-radius:10px;padding:8px 18px;font-size:.88rem;font-weight:700;color:#510580;cursor:pointer;transition:all .15s}
    .gu-pill2:hover,.gu-pill2.active{background:#510580;color:white;border-color:#510580}
    .dong-area,.dong-area2{margin-top:10px;background:white;border-radius:10px;padding:12px 14px;border:1px solid #e8d6f5;display:none}
    .dong-area-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
    .dong-area-title{font-size:.82rem;font-weight:700;color:#510580}
    .dong-area-close{font-size:.75rem;color:#9b6cc0;cursor:pointer;padding:2px 8px;border-radius:6px;background:#f0e6fc}
    .dong-chips{display:flex;flex-wrap:wrap;gap:6px}
    .dong-chip{background:#faf5ff;border:1px solid #e8d6f5;border-radius:8px;padding:6px 13px;font-size:.82rem;color:#370558;text-decoration:none;transition:all .15s;white-space:nowrap}
    .dong-chip:hover{background:#510580;color:white;border-color:#510580}
    footer{background:#370558;color:rgba(255,255,255,.45);text-align:center;padding:20px;font-size:.75rem;line-height:1.8;margin-top:20px}
    footer p{color:rgba(255,255,255,.45);margin:2px 0}
    footer a{color:rgba(255,255,255,.6);text-decoration:none}
    footer a{color:rgba(255,255,255,.6);text-decoration:none}
  </style>
</head>
<body>
${HEADER_HTML}
<div class="hero">
  <h1>지역별 과외 찾기</h1>
  <p>원하는 지역을 선택하고 과목과 학년을 고르세요</p>
</div>
<div class="filter-bar">
  <span class="filter-label">학년</span>
  <select id="sel-grade" class="filter-select">
    <option value="">전체</option>
    <option>초등</option><option>중등</option><option>고등</option>
  </select>
  <span class="filter-label">과목</span>
  <select id="sel-subject" class="filter-select">
    <option value="">전체</option>
    <option>국어</option><option>영어</option><option>수학</option><option>과학</option><option>사회</option><option>한국사</option>
  </select>
  <input type="text" id="search-input" class="filter-search" placeholder="🔍 지역 검색...">
</div>
<div class="main-wrap" id="cityContainer">
${cityBlocksHtml}
</div>
${FOOTER_HTML}
${FLOAT_HTML}
<script>
function closeAll(cityKey) {
  document.querySelectorAll('[id^="siarea_' + cityKey + '"]').forEach(el => { el.style.display = 'none'; });
  document.querySelectorAll('[id^="sipill_' + cityKey + '"]').forEach(el => { el.classList.remove('active'); });
  document.querySelectorAll('[id^="dong_' + cityKey + '"]').forEach(el => { el.style.display = 'none'; });
  document.querySelectorAll('[id^="pill_' + cityKey + '"]').forEach(el => { el.classList.remove('active'); });
}
function toggleSi(cityKey, siKey) {
  const area = document.getElementById('siarea_' + siKey);
  const pill = document.getElementById('sipill_' + siKey);
  const isOpen = area.style.display !== 'none';
  closeAll(cityKey);
  if (!isOpen) { area.style.display = 'block'; pill.classList.add('active'); }
}
function toggleDong2(siKey, guKey) {
  const area = document.getElementById('dong2_' + guKey);
  const pill = document.getElementById('pill2_' + guKey);
  const isOpen = area.style.display !== 'none';
  document.querySelectorAll('[id^="dong2_' + siKey + '"]').forEach(el => { el.style.display = 'none'; });
  document.querySelectorAll('[id^="pill2_' + siKey + '"]').forEach(el => { el.classList.remove('active'); });
  if (!isOpen) { area.style.display = 'block'; pill.classList.add('active'); updateDongLinks(); }
}
function closeDong2(siKey, guKey) {
  document.getElementById('dong2_' + guKey).style.display = 'none';
  document.getElementById('pill2_' + guKey).classList.remove('active');
}
function toggleDong(cityKey, guKey) {
  const area = document.getElementById('dong_' + guKey);
  const pill = document.getElementById('pill_' + guKey);
  const isOpen = area.style.display !== 'none';
  closeAll(cityKey);
  if (!isOpen) { area.style.display = 'block'; pill.classList.add('active'); updateDongLinks(); }
}
function closeDong(cityKey, guKey) {
  document.getElementById('dong_' + guKey).style.display = 'none';
  document.getElementById('pill_' + guKey).classList.remove('active');
}
function updateDongLinks() {
  const grade = document.getElementById('sel-grade').value || '중등';
  const subject = document.getElementById('sel-subject').value || '수학';
  document.querySelectorAll('.dong-chip, a.gu-pill[data-dong]').forEach(chip => {
    const city = chip.dataset.city;
    const gu = chip.dataset.gu;
    const dong = chip.dataset.dong;
    if (city && gu && dong) {
      const href = '/' + city + '-' + gu + '-' + dong + '-' + grade + '-' + subject + '-과외/';
      chip.setAttribute('href', href.replace(/ /g, '-'));
    }
  });
}
document.getElementById('sel-grade').addEventListener('change', updateDongLinks);
document.getElementById('sel-subject').addEventListener('change', updateDongLinks);
document.getElementById('search-input').addEventListener('input', function() {
  const q = this.value.trim().toLowerCase();
  document.querySelectorAll('.city-block').forEach(block => {
    block.style.display = q === '' || block.textContent.toLowerCase().includes(q) ? '' : 'none';
  });
});

// URL 해시(#city-시도이름)로 진입 시 해당 시도로 자동 스크롤 + 강조
(function(){
  function scrollToCity(){
    var hash = window.location.hash;
    if (!hash || !hash.startsWith('#city-')) return;
    var target = document.querySelector(decodeURIComponent(hash));
    if (!target) return;
    // 약간의 지연으로 sticky filter-bar 고려
    setTimeout(function(){
      // sticky 헤더(.site-header) + filter-bar 높이만큼 offset
      var header = document.querySelector('.site-header');
      var filterBar = document.querySelector('.filter-bar');
      var offset = 0;
      if (header) offset += header.offsetHeight;
      if (filterBar) offset += filterBar.offsetHeight;
      offset += 12; // 여유 공간
      var rect = target.getBoundingClientRect();
      var targetY = window.pageYOffset + rect.top - offset;
      window.scrollTo({top: targetY, behavior: 'smooth'});
      // 강조 효과: 잠깐 핑크 테두리·그림자
      target.style.transition = 'box-shadow .3s, border-color .3s';
      target.style.boxShadow = '0 0 0 3px #e8439a, 0 8px 20px rgba(232,67,154,.3)';
      target.style.borderColor = '#e8439a';
      setTimeout(function(){
        target.style.boxShadow = '';
        target.style.borderColor = '';
      }, 2500);
    }, 100);
  }
  scrollToCity();
  window.addEventListener('hashchange', scrollToCity);
})();
</script>
</body>
</html>`;
}

